import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Build a diameter-normalized packing by disk relaxation and polishing.

    Several concentric-ring seeds are relaxed against a trial separation inside
    the unit disk, then the best result is polished by a deterministic SLSQP
    max-min solve and retained only if it beats the triangular-shell fallback.
    """
    from itertools import combinations

    def shell_fallback() -> np.ndarray:
        s = np.sqrt(3.0)
        a = np.arange(6.0) * (np.pi / 3.0)
        b = np.pi / 6.0 + a
        c = np.arange(3.0) * (2.0 * np.pi / 3.0)
        return np.vstack((
            [[0.0, 0.0]],
            np.column_stack((np.cos(a), np.sin(a))),
            s * np.column_stack((np.cos(b), np.sin(b))),
            2.0 * np.column_stack((np.cos(c), np.sin(c))),
        )) / np.sqrt(13.0)

    def score(p):
        d = p[:, None, :] - p[None, :, :]
        q = np.sum(d * d, axis=2)
        q = q[np.triu_indices(16, 1)]
        return float(np.min(q) / np.max(q))

    def seed(rings, phases):
        out = []
        for n, r, ph in zip(rings, (0.0, 0.58, 1.0), phases):
            if n == 1:
                out.append([0.0, 0.0])
            else:
                t = ph + 2.0 * np.pi * np.arange(n) / n
                out.extend(np.column_stack((r * np.cos(t), r * np.sin(t))))
        return np.asarray(out, dtype=float)

    seeds = [
        seed((1, 5, 10), (0.0, 0.13, 0.31)),
        seed((1, 6, 9), (0.0, 0.09, 0.27)),
        seed((4, 12), (0.07, 0.19)),
    ]
    pairs = list(combinations(range(16), 2))

    def relax(x, target, sweeps=420):
        x = x.copy()
        for _ in range(sweeps):
            move = np.zeros_like(x)
            for i, j in pairs:
                v = x[i] - x[j]
                d = np.sqrt(np.dot(v, v))
                if d < target:
                    if d < 1e-10:
                        v = np.array([1.0, 0.173])
                        d = np.linalg.norm(v)
                    z = 0.5 * (target - d) * v / d
                    move[i] += z
                    move[j] -= z
            x += 0.72 * move
            r = np.sqrt(np.sum(x * x, axis=1))
            over = r > 1.0
            x[over] /= r[over, None]
        d = x[:, None, :] - x[None, :, :]
        q = np.sum(d * d, axis=2)[np.triu_indices(16, 1)]
        return x, float(np.sqrt(max(0.0, np.min(q))))

    best = shell_fallback()
    best_value = score(best)
    for initial in seeds:
        lo, hi = 0.20, 0.40
        candidate = initial
        for _ in range(22):
            mid = (lo + hi) * 0.5
            trial, achieved = relax(initial, mid)
            if achieved + 2e-6 >= mid:
                lo, candidate = mid, trial
            else:
                hi = mid

        try:
            from scipy.optimize import minimize
            z0 = np.r_[candidate.ravel(), lo * 0.995]

            def unpack(z):
                return z[:-1].reshape(16, 2)

            def constraints(z):
                p = unpack(z)
                t = z[-1]
                d = p[:, None, :] - p[None, :, :]
                q = np.sum(d * d, axis=2)[np.triu_indices(16, 1)]
                disk = 1.0 - np.sum(p * p, axis=1)
                return np.r_[q - t * t, disk]

            result = minimize(
                lambda z: -z[-1], z0, method="SLSQP",
                bounds=[(-1.0, 1.0)] * 32 + [(0.05, 0.5)],
                constraints={"type": "ineq", "fun": constraints},
                options={"maxiter": 1400, "ftol": 2e-11, "disp": False},
            )
            if result.success and np.all(np.isfinite(result.x)):
                candidate = unpack(result.x)
        except ImportError:
            pass

        candidate = np.clip(candidate, -1.0, 1.0)
        value = score(candidate)
        if value > best_value and value > 1.0 / 13.0:
            best, best_value = candidate, value

    return best
